                          <nav> <a href="index.php">Home</a> <a href="technicians.php">Find Technicians</a> <a href="login.php">Login</a> </nav> </div> </header> <div class="tech-layout"> <!-- Sidebar --> <aside class="tech-sidebar"> <h2>Technician Portal</h2> <p class="sidebar-label">Workspace</p> <nav class="tech-nav"> <a href="technician-dashboard.php" class="active"> Dashboard </a> <a href="#requests">Job Requests</a> <a href="#portfolio">My Portfolio</a> <a href="#profile">My Profile</a> <a href="technicians.php">View Website</a> </nav> <p class="sidebar-label">Account</p> <nav class="tech-nav"> <a href="login.php">Log Out</a> </nav> </aside> <!-- Main Content --> <main class="tech-main"> <div class="tech-topbar"> <div> <h1>Technician Dashboard</h1> <span class="muted"> Manage your work and customer requests. </span> </div> <div class="avatar">MT</div> </div> <!-- Welcome --> <section class="welcome-banner"> <div> <h2> Welcome back, <?php echo htmlspecialchars($technicianName); ?>! </h2> <p> Keep your professional profile updated and respond to new job requests. </p> </div> <a href="#requests" class="primary-button"> View Job Requests </a> </section> <!-- Statistics --> <section class="stats-grid"> <div class="stat-card"> <span>New Job Requests</span> <strong><?php echo $stats["requests"]; ?></strong> <span>Sample requests</span> </div> <div class="stat-card"> <span>Accepted Jobs</span> <strong><?php echo $stats["accepted"]; ?></strong> <span>Sample accepted jobs</span> </div> <div class="stat-card"> <span>Completed Jobs</span> <strong><?php echo $stats["completed"]; ?></strong> <span>Sample completed jobs</span> </div> </section> <!-- Job Requests --> <section id="requests"> <div class="section-heading"> <h2>Recent Job Requests</h2> </div> <div class="content-card"> <?php foreach ($jobRequests as $index => $job): ?> <div class="job-row" id="job-<?php echo $index; ?>"> <div> <strong> <?php echo htmlspecialchars($job["customer"]); ?> </strong> <small>Customer</small> </div> <div> <strong> <?php echo htmlspecialchars($job["service"]); ?> </strong> <small> Location: <?php echo htmlspecialchars($job["location"]); ?> </small> </div> <div> <strong> <?php echo htmlspecialchars($job["date"]); ?> </strong> <span class="status <?php echo $job["status"] === "Accepted" ? "status-accepted" : "status-pending"; ?>" id="status-<?php echo $index; ?>"> <?php echo htmlspecialchars($job["status"]); ?> </span> </div> <div> <?php if ($job["status"] === "Pending"): ?> <div class="job-actions"> <button type="button" class="action-button" onclick="updateJob(<?php echo $index; ?>, 'Accepted')"> Accept </button> <button type="button" class="action-button secondary" onclick="updateJob(<?php echo $index; ?>, 'Declined')"> Decline </button> </div> <?php else: ?> <small>Request received</small> <?php endif; ?> </div> </div> <?php endforeach; ?> </div> <p class="muted" id="jobMessage" aria-live="polite"></p> </section> <!-- Portfolio --> <section id="portfolio"> <div class="section-heading"> <h2>My Portfolio</h2> </div> <div class="photo-grid"> <?php foreach ($workPhotos as $photo): ?> <article class="photo-card"> <div class="photo-placeholder" aria-hidden="true"> &#128247; </div> <h3> <?php echo htmlspecialchars($photo["title"]); ?> </h3> <p> <?php echo htmlspecialchars($photo["description"]); ?> </p> </article> <?php endforeach; ?> </div> <p class="muted"> Portfolio photo uploads will be connected when the backend file-upload feature is implemented. </p> </section> <!-- Profile --> <section id="profile"> <div class="section-heading"> <h2>My Professional Profile</h2> </div> <div class="content-card profile-card"> <p> <strong>Name:</strong> <?php echo htmlspecialchars($technicianName); ?> </p> <p><strong>Profession:</strong> Electrician</p> <p><strong>Location:</strong> Limbe</p> <p><strong>Experience:</strong> 5 years</p> <p class="muted"> Profile editing will be connected to your technician account when the backend is ready. </p> <a href="techniciandetails.php" class="outline-button"> View Sample Public Profile </a> </div> </section> <footer class="tech-footer"> &copy; <?php echo date("Y"); ?> TechConnect. All rights reserved. </footer> </main> </div> 
                            <script> // Frontend demonstration only. // Changes are not saved to a database. function updateJob(index, newStatus) { const statusElement = document.getElementById("status-" + index); const message = document.getElementById("jobMessage"); const jobRow = document.getElementById("job-" + index); if (!statusElement || !jobRow) { return; } statusElement.textContent = newStatus; statusElement.className = "status"; if (newStatus === "Accepted") { statusElement.classList.add("status-accepted"); } else { statusElement.style.background = "#fee2e2"; statusElement.style.color = "#991b1b"; } const actions = jobRow.querySelector(".job-actions"); if (actions) { actions.innerHTML = "<small>Request " + newStatus.toLowerCase() + " (demo)</small>"; } message.textContent = "Demo: job request " + newStatus.toLowerCase() + ". This change has not been saved to a database."; } </script> </body> </html>